    # separator lines: full rows/cols of a single non-bg color
    Hlines=[r for r in range(H) if len(set(inp[r]))==1 and inp[r][0]!=bg]
    Vlines=[c for c in range(W) if len({inp[r][c] for r in range(H)})==1 and inp[0][c]!=bg]
    res=[r[:] for r in inp]
    changed=True
    while changed:
        changed=False
        newpos=set()
        # collect new seed colors
        seeds={(r,c,inp[r][c]) for r in range(H) for c in range(W) if inp[r][c]!=bg}
        for r,c,v in seeds:
            for a in Hlines:
                nr=2*a-r
                if 0<=nr<H: newpos.add((nr,c,v))
            for b in Vlines:
                nc=2*b-c
                if 0<=nc<W: newpos.add((r,nc,v))
        if newpos:
            changed=True
            for r,c,v in newpos:
                res[r][c]=v
    return res

